#define assert(x) ((void)0)

template<class T>
class list
{
    struct node { node *next; node *previous; T value; };
    node *sentinel;
public:
    T &back() { return sentinel->previous->value; }
};

class SpecialMeter
{
public:
    void Increase(float value);
};

class IGOFrontEnd
{
public:
    void OnTrickChange(int playerIdx, bool seriesChange);
};

class FEManager
{
public:
    IGOFrontEnd *IGO;
};

extern FEManager frontendmanager;

class ScoringManager
{
public:
    enum ATTRIBUTE
    {
        ATTR_DIST_LIP,
        ATTR_DIST_MOUTH,
        ATTR_TIME_TOTAL,
        ATTR_TIME_DELTA,
        ATTR_TO_FAKEY,
        ATTR_FROM_FLOATER,
        ATTR_HOP
    };

    enum { MOD_FROM_FLOATER, MOD_TO_FAKEY, MOD_HOP };

    class Series
    {
        void *levelTricks;
        void *tricks;
        int numSpins;
        int landing;
    public:
        int flags;
    };

    class Chain
    {
        void *levelTricks;
        float multAdder;
    public:
        list<Series> series;
        float GetSickness() const;
    };

private:
    char padding0[0x0C];
    int playerIdx;
    SpecialMeter *specialMeter;
    char padding1[0x198];
    Chain chain;

public:
    void UpdateLastSeries(const ATTRIBUTE attr, const bool b);
};

__asm__(".equ frontendmanager, 0x003E7728");
__asm__(".equ GetSickness__CQ214ScoringManager5Chain, 0x002490C0");
__asm__(".equ Increase__12SpecialMeterf, 0x00250FB8");
__asm__(".equ OnTrickChange__11IGOFrontEndib, 0x0017BD08");

void ScoringManager::UpdateLastSeries(const ScoringManager::ATTRIBUTE attr, const bool b)
{
	Series &	series = chain.series.back();
	float		oldSickness;
	int			flag;

	oldSickness = chain.GetSickness();

	switch (attr)
	{
	case ATTR_FROM_FLOATER :
		flag = 1 << MOD_FROM_FLOATER;
		if (b)
			series.flags |= flag;
		else
			series.flags &= ~flag;
		frontendmanager.IGO->OnTrickChange(playerIdx, false);
		break;

	case ATTR_TO_FAKEY :
		flag = 1 << MOD_TO_FAKEY;
		if (b)
			series.flags |= flag;
		else
			series.flags &= ~flag;
		frontendmanager.IGO->OnTrickChange(playerIdx, false);
		break;

	case ATTR_HOP :
		flag = 1 << MOD_HOP;
		if (b)
			series.flags |= flag;
		else
			series.flags &= ~flag;
		frontendmanager.IGO->OnTrickChange(playerIdx, false);
		break;

	default : assert(0);
	}

	specialMeter->Increase(chain.GetSickness() - oldSickness);
}
